<?php
declare(strict_types=1);
require_once __DIR__.'/core.php';
function r_proposal(string $id,array $a,string $actor): string {
 $book=json_decode(file_get_contents(dirname(__DIR__).'/config/pricebook.json'),true,512,JSON_THROW_ON_ERROR);
 $type=r_text($a,'system_type',20);$code=r_text($a,'package_code',60);$variant=r_text($a,'panel_variant',20);
 if(!in_array($type,['ongrid','hybrid'],true)||!in_array($variant,['full_dcr','mixed'],true))throw new RuntimeException('Choose package and panel scope.');
 $matches=array_values(array_filter($book['plans'][$type],fn($p)=>$p['code']===$code));if(count($matches)!==1)throw new RuntimeException('Choose an approved package.');$p=$matches[0];if($variant==='mixed'&&$p['kw']<=3)throw new RuntimeException('Mixed scope only available above 3 kW.');
 $scope=r_text($a,'confirmed_scope',3000);$exclusions=r_text($a,'exclusions',2000);$site=r_text($a,'site_assumptions',2000);if(!$scope||!$site||!$exclusions||($a['scope_confirmed']??'')!=='1')throw new RuntimeException('Staff must confirm equipment, site scope, exclusions and assumptions.');
 $price=$variant==='mixed'?$p['low']:$p['price'];$dp=round($price*($price<=270000?.1:.2));$loan=$price-$dp;if($loan>600000)throw new RuntimeException('Loan exceeds the verified scheme limit. Confirm a larger contribution or a documented lender route before preparing a financed proposal.');$rate=$loan<=200000?5.75:7.9;$monthly=$rate/1200;$emi=round($loan*$monthly/(1-pow(1+$monthly,-120)),2);
 $text="DRAFT — STAFF REVIEW REQUIRED; NOT SENT\nDakshayani Enterprises · Residential solar\nPrice book {$book['version']} · effective {$book['effective_date']}\nPackage {$p['code']} · {$p['kw']} kW · $type · $variant\nConfiguration: {$p['config']}\nPackage price incl. GST and standard installation: INR $price\nIllustrative upfront contribution: INR $dp\nIllustrative loan principal: INR $loan\nFloating rate illustration: $rate% annually · 120 equal payments, no moratorium modelled\nIllustrative EMI before any subsidy: INR $emi\nTotal instalments: INR ".round($emi*120,2)." · illustrative total interest: INR ".round($emi*120-$loan,2)."\nBank approval, rate, margin, eligible costs, fees, moratorium and disbursement may differ. Loan over INR600000 needs another verified route or larger contribution.\nNo subsidy deducted. Eligible residential CFA requires approved DCR configuration, portal process, DISCOM approval and commissioning. Mixed DCR/non-DCR eligibility unresolved; hybrid eligibility must be separately verified. Credit timing is not guaranteed.\nNo electricity saving is guaranteed or assumed to pay an EMI. Site generation, paid consumption, tariff, fixed charges and net metering need review.\nOn-grid normally stops during an outage. Hybrid backup depends on confirmed battery chemistry, voltage, Ah, usable depth of discharge and appliance loads. Lead-acid base package; lithium upgrade and battery replacement cost extra unless expressly quoted.\nStaff-confirmed scope/equipment: $scope\nSite assumptions: $site\nExclusions and extra costs: $exclusions\nValidity: 7 calendar days from preparation, subject to site confirmation and availability.\nResponsibilities: homeowner supplies correct connection/bill information and roof authority; team confirms design, safe structure, written scope, payment milestones and commissioning process before acceptance.\nNext step: review this draft with the homeowner; confirm final scope and payment milestones in writing before sending a contractual quotation.\n";
 return r_state(function(&$s)use($id,$a,$actor,$book,$text,$price){if(!isset($s['leads'][$id]))throw new RuntimeException('Record not found.');$l=&$s['leads'][$id];if((int)($a['version']??0)!==$l['version'])throw new RuntimeException('Refresh record before preparing proposal.');$v=count($l['proposals']??[])+1;$ref='RES-'.$id.'-P'.$v;$l['proposals'][]=['reference'=>$ref,'version'=>$v,'at'=>gmdate('c'),'actor'=>$actor,'pricebook'=>$book['version'],'price'=>$price,'status'=>'draft_not_sent','text'=>$text];$l['history'][]=['at'=>gmdate('c'),'actor'=>$actor,'kind'=>'proposal_draft','note'=>$ref.' prepared, not sent'];$l['version']++;$l['updated_at']=gmdate('c');return $ref;});
}
